import{_ as i,o as e,c as t,a2 as l}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"Anki 集成","description":"","frontmatter":{},"headers":[],"relativePath":"guide/anki.md","filePath":"guide/anki.md","lastUpdated":1787830168000}'),r={name:"guide/anki.md"};function o(d,a,n,c,h,f){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="anki-集成" tabindex="-1">Anki 集成 <a class="header-anchor" href="#anki-集成" aria-label="Permalink to &quot;Anki 集成&quot;">​</a></h1><p>Turna 的 Android 生产路径内嵌 Official Anki Core（rslib FFI）。<code>.apkg</code> 导入后由 Official Collection 持有 note、card、revlog 与正式调度状态。<code>.colpkg</code> 当前不属于生产导入合同。</p><p>产品页演示见 <a href="./../../anki.html">anki.html</a>。</p><h2 id="数据所有权" tabindex="-1">数据所有权 <a class="header-anchor" href="#数据所有权" aria-label="Permalink to &quot;数据所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>所有者</th></tr></thead><tbody><tr><td>Official note / card / revlog</td><td>Official Collection</td></tr><tr><td>Official 正式评分</td><td>Official scheduler</td></tr><tr><td>课程树展示</td><td>从 Official 来源建立的投影</td></tr><tr><td>课程原生词汇与表达</td><td>Turna 课程数据库与 Dart FSRS</td></tr></tbody></table><p>两类项目可显示在统一复习入口，但不混写调度状态。Official runtime 不可用时，Official 来源必须 fail closed。</p><h2 id="导入阶段" tabindex="-1">导入阶段 <a class="header-anchor" href="#导入阶段" aria-label="Permalink to &quot;导入阶段&quot;">​</a></h2><ol><li>选择 <code>.apkg</code>。</li><li>生成一次导入执行计划。</li><li>检查 notetype 映射与组织预览。</li><li>写入 Official Collection。</li><li>建立课程投影与 source scope。</li><li>通过共享复习入口启动 Official review session。</li></ol><h2 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h2><ul><li>默认使用 Flutter HTML。</li><li>需要 JavaScript、MathJax 或现场解密时才使用移动 WebView。</li><li>网络与 JavaScript 分别授权，网络默认完全离线。</li><li>渲染失败依次降级，不能让复习停在空白卡。</li></ul><h2 id="数据在哪" tabindex="-1">数据在哪 <a class="header-anchor" href="#数据在哪" aria-label="Permalink to &quot;数据在哪&quot;">​</a></h2><p>牌组、媒体与复习记录保存在设备本地，不要求账号或 AnkiWeb。删除牌组、清缓存和清除应用数据是不同操作。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-import">导入 Anki 牌组</a></li><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li></ul>',14)])])}const p=i(r,[["render",o]]);export{u as __pageData,p as default};
